-- GENERATED by `wfj generate` from data/quest/quest-0092.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [92109] = { "はじめてのAlchemyセット", "Empty Vialを5個、Silverleafを5個、Peacebloomを5個集め、WestfallのMoonbrookの納屋の中にいる若き錬金術師志望の子のところへ持って行ってください。", "えっと……こんにちは、旅人さん。知らない人と話しちゃいけないんだけど……ねえ、リュックから飛び出してるそのピカピカの瓶は何のため？ 錬金術師なの？ すっごーい！\n\n大きくなったら、私も錬金術師になりたいの。パパは自分の薬草で遊ばせてくれないんだ。危ないからだって。\n\nでも、今から勉強を始めたいの。材料を集めてきてくれないかな、お願い？", nil, nil, 0xea2205a4, 0x9455f16a, 0x3ea4b9d3, nil, nil, "...mm", nil, nil, 0x543226a7, nil, nil },
  [92110] = { "はじめての本物のポーション", "WestfallのMoonbrookの納屋の中にいる若き錬金術師志望の子のために、Murloc Eyeを3個集めてください。", "わあ、私の初めてのポーション！ 最初に始めたとき、あの二つのハーブを混ぜるとポーションが真っ赤な色に変わるって知ってた？\n\n楽しかったけど、お花をいくつか混ぜるだけじゃ、パパがやってるような錬金術とは違う気がするの。パパは他の材料も使うんだよ。\n\n他に何を使えばいいかわからないから、最初に思いついたものを試してみよう！ ええと……murloc eyesとか？ すっごく気持ち悪いけど、きっと何か起きるよ。", nil, nil, 0x694e0f66, 0x5c5c86d7, 0xcdc27db4, nil, nil, "...mm" },
  [92124] = { "蔵書の棚卸し", "図書館にいるBrother Paxtonの助手、Danielと話してください。", "行方不明の本が何冊あるか確かめないと！\n\n役立たずの助手、Danielと話してきてくれ。彼ならすぐに目録を調べて、問題がどれほど深刻か教えてくれるだろう。\n\nあいつはElwynn Forestのいろいろな職業に夢中なんだ。私を手伝う大事な仕事をそっちのけで、そればかりに気を取られている。\n\n職業の話を延々とさせずに、私の本に何があったのか聞き出してくれ！", nil, nil, 0x0231e44e, 0xe64d5a5a, 0x1c2a73d0, nil, nil, "...mm" },
  [92401] = { "怯えた頼み", "Ruins of LordaeronでのEdward Heartweaverの失踪を調べてください。", "夫のEdwardのことなの……\n\nLordaeronの廃墟にある墓地へ毎週通っているんだけど、まだ戻ってこないの。Arthasが都を滅ぼした時に息子を失って、遺体が見つからなかったことで、私の愛しいEdwardは今も罪悪感と悲しみでいっぱいなの。あの荒れ果てた廃墟を探し回るのはやめてと言ったんだけど、彼は諦めようとしない。心配しないようにしているけど、もう何日も経っているわ。\n\nあそこには私の手に負えないものがいるけど、もし引き受けてくれるなら、夫がどうなったのか知りたいの。", nil, nil, 0xa5170225, 0x5b830c47, 0x9ca0aaa6, nil, nil, "...mm" },
  [92415] = { "愛していると忘れないで", "Blood-Stained LetterをStormwind CityにいるOrphan Matron Nightingaleのところへ持って行ってください。", "<引き裂かれ、汚れた羊皮紙の束が、アンデッドに踏み荒らされた墓地の地面でかろうじて残っていた。Heartweaver家の行方不明の子供について書かれている。Stormwind Cityの孤児院の寮母なら何か知っているかもしれない。>", nil, nil, 0x920a601f, 0xab38aea1, 0x10864cbe, nil, nil, "...mm" },
  [92421] = { "光の正義", "UndercityにいるMorbin Lightbaneのために、The Ruins of LordaeronでIntact Limbsを$N1個集めてください。", "Forsakenのパラディンとして、我らがDark Ladyの意志を果たしつつ、民の必要に応えるのが私の務めだ。幸いにも、その両方を成し遂げる機会がある。\n\nUndercityの上では、scourgeが今も大群でのさばっている。我らの軍勢は土地を取り戻そうとして減っていき、腐った肉は繋ぎ直せない。代わりがなければな。\n\n我らが栄光ある隊長Garek Bandarionがまだいてくれたなら、彼が何を望むか私には分かる。彼が始めたことを成し遂げ、同胞を癒やすことだ。Lordaeronのために！", nil, nil, 0x37a29ead, 0x86900340, 0x16f288f0, nil, nil, "...mm" },
  [92422] = { "Rath'maelの怒り", "BrillにいるDeathguard Kristofのために、Ruins of LordaeronでRath'maelを倒してください。", "Ruins of Lordaeronの奥深くにあるLordamere Overlookから報告が入った。邪悪な霧が通りと墓地を覆い、そこにいるscourgeにある程度の隠れ蓑を与えているという。\n\n斥候によれば、霧は奴らの中に現れた新たな力、Rath'maelという名のネクロマンサーが呼び出しているらしい。こいつばかりは待っている余裕はない、{name}。\n\n仲間がいるなら呼び集めて、Forsakenのために力を貸してもらえ。この怪物を我らの地から追い出せ。", nil, nil, 0x5b21ca69, 0x89893476, 0x68ec1579, nil, nil, "...mm" },
  [92454] = { "ようこそ！", "Thendal Grove Gift VoucherをDalia Windbreezeのところへ持って行ってください。", "World of Warcraftへようこそ！\n\nWorld of Warcraft Collector's Editionをご購入いただいた特別な感謝として、このgift voucherをThendal GroveのDalia Windbreezeに渡してください。冒険と栄光を求める旅に同行する、小さな仲間が贈られます。\n\n改めてありがとうございます。World of Warcraftでの滞在をお楽しみください！", nil, nil, 0xd6adcb4f, 0x498e8e33, 0x3ed9c7cd, nil, nil, "...mm" },
  [92460] = { "成年", "Thendal GroveにいるRorian the Dayseekerと話してください。", "まあ、目を輝かせて冒険の準備万端ね！ あなたの到着を待っていたのよ。ここThendal Villageで、あなたの助けをとても期待していたの。これから起こることに、緊張とわくわくでいっぱいでしょうね。何しろ、成人を迎えるのは一生に一度だけだもの。\n\n<Aileeが優しく微笑む。>\n\nさあ、村の長であるRorian the Dayseekerを訪ねて。すぐ西の大父樹の入口にいるわ。彼があなたの旅を始めさせてくれるわ。", nil, nil, 0x09074aad, 0x47c75d71, 0x0b5f719a, nil, nil, "...mm" },
  [92461] = { "調和と均衡", "Thendal GroveでVuldren Juvenileを8体倒してください。", "我らの民にとって大いなる不確かさの時代だ。前例のない困難に直面し、大胆な解決が必要になるかもしれぬ。だが、ここThendal Groveでは日常のありふれた問題にも向き合わねばならぬ。例えば、最近のvuldrenの数の持続不可能な増加だ。\n\nvuldrenは我らの生態系に欠かせない存在だ。しかし、Thendal Groveのすべての生き物が分かち合う繊細な調和を保つには、偏りを正さねばならぬ。\n\n東へ向かい、そこにいるvuldrenを間引いてくれ。", nil, nil, 0xe894e8ee, 0xa0a3f81d, 0xa21181a9, nil, nil, "...mm" },
  [92462] = { "害虫蔓延の調査", "Thendal GroveでPesky Cirrusfliesを8体倒してください。", "最近、うちのレンジャーの一人が、ここThendal Groveでcirrusfliesが大量発生していると報告してきた。\n\ncirrusfliesの群れは大きくなりすぎると危険になりうる。どうかGroveの東の端へ向かい、できるだけ多く駆除してくれ。", nil, nil, 0x79cd311b, 0xbb00ccfb, 0x08bf04cb, nil, nil, "...mm" },
  [92463] = { "Cirrusflyの女王", "Thendal GroveでCirrusfly Queenを倒してください。", "森にこの虫がそれほどうじゃうじゃいるなら、働き虫を倒すだけでは足りないだろう。\n\n森の奥へ進んで、女王を見つけてくれ。巣の近くにいて、もっと大きく凶暴な兵隊に囲まれているはずだから、気をつけてな。\n\n倒したらここへ戻ってきてくれ。これで、このあたりで考える問題が1つ減る。", nil, nil, 0x83a6ddbe, 0x682745f5, 0x7e74d152, nil, nil, "...mm" },
  [92464] = { "エレメンタルの騒乱", "Thendal GroveにいるYala Windwatcherと話してください。", "精霊の恩人たちが去ってから、我々は1つの騒ぎから次の騒ぎへと移っているだけのようだ。今直面している問題は、北東の立石の近くにいる風の顕現たちが興奮していることだ。\n\nかつてここに住んでいた知性ある風の精霊とは違い、この単純な精たちは真の自我を持たず、周囲の生き物の力や感情、意図にそのまま反応する。\n\n弟子のYala Windwatcherが様子を見に行った。彼女を探して、何が分かったか聞いてきてくれ。", nil, nil, 0x9b167222, 0x0bc6b5fa, 0x7eb11290, nil, nil, "...mm" },
  [92465] = { "扇動者たち", "Thendal GroveでRoiling Windを$N1体とAl'Aketh Convertを$N2人倒してください。", "Al'Aketh cultはこの島の災いだ。この教団の者たちこそ、ここに住む単純な風の精たちを興奮させ、凶暴にしている張本人に違いない。\n\n残念だが、誰かを傷つける前にここで荒れ狂う風を散らさねばならない。そして教団に、この森では歓迎されないとはっきり知らしめる必要もある。\n\n力を貸してくれるか、{class}？", nil, nil, 0xbed3e8bb, 0xcd6603dd, 0x1f47f35d, nil, nil, "...mm" },
  [92466] = { "大地の呼び声", "Signet of AkirをWindshaper Boroのところへ持って行ってください。", "我らの繁栄の多くは風の元素のおかげだが、我らの歩む道は、4つの主要な元素すべての呼び声に従い、それぞれの試練を受けることを求める。だが、最初の試練を本格的に始める前に、そなたの決意の強さを示さねばならぬ。\n\n東の立石へ向かえ。Al'Akethの改宗者の一団がそこで目撃されており、追い払わねばならぬ。そこの教団員と対決し、そなたの行いの証として、奴らの印章を1つ持ってきてくれ。", nil, nil, 0xe316c17f, 0x56d019a1, 0x6a8b0ee0, nil, nil, "...mm" },
  [92467] = { "大地の呼び声", "Rise of Spiritsを見つけ、Earth Saptaを飲んでください。", "saptaとは、我らの魂を元素と結びつけるために作られる飲み物だ。魔法が融け込んだこの薬は、意志の強い者に、他の誰にも見えぬ形で元素を見せてくれる。そなたの魂はsaptaが作られた元素と結ばれる。そしてその作り方を知るのは、ごく一部のシャーマンだけだ。\n\nsaptaは必ず聖なる場所で飲むもので、それ以外の場所では決して飲まぬ――それを覚えておけ。\n\nここから北東の峠を登った先のRise of Spiritsを探せ。そこでsaptaを飲めば……まあ、見るべきものが見えるだろう。", nil, nil, 0xe316c17f, 0xf6800b6c, 0xa4d7d340, nil, nil, "...mm" },
  [92468] = { "大地の呼び声", "Rough QuartzをThendal GroveにいるWindshaper Borosのところへ持って行ってください。", "このRough Quartzを我から受け取り、我らが出会った証として、そなたがWindshaper Boroと呼ぶ者へ持っていくがよい。彼がそなたのためにトーテムを作るであろう。そしてこの欠片がその心臓となる。小さく見えようとも、大きさは問題ではなく、どんなに小さなものでも多くのものより長く残りうることを、そなたはいずれ知るであろう。\n\n忍耐せよ、{name}。強くあれ。そして知恵を求めよ。これこそ元素がそなたに求めるものだ。最後には、そなたは大地と1つになるであろう――大地を敬え、大地がそなたを敬うように。", nil, nil, 0xe316c17f, 0x5d706269, 0x79a2fea5, nil, nil, "...mm" },
  [92469] = { "Rorianのもとへ", "Al'Akethの知らせを、Thendal GroveにいるRorian the Dayseekerに伝えてください。", "ここはもう十分だ、{class}。俺は残って、下にいる残党を片付ける。\n\nVillageへ戻って、Rorianに教団がいることを伝えてくれ。彼はいい顔をしないだろう。", nil, nil, 0xd40ca8eb, 0x40558191, 0xc0e405c7, nil, nil, "...mm" },
  [92470] = { "穢れた母獣", "Thendal GroveでUrsera Scavengerを8体倒し、巣の母であるUrs'anahの首を手に入れてください。", "Rorianから、私があなたを見ていたと聞いたでしょう。今、あなたに決意の試練を授けます。ただし、警告しておきます――それはあなたを大きな危険へ送り込むことになります。\n\n南の洞窟へ行ってください。そこにいるurseraの数を減らし、レンジャーたちが「Urs'anah」と呼ぶ、彼らの女家長を見つけてください。彼女を倒し、その死の証を持ってきてください。それを成し遂げれば、あなたは自分の道で重要な一歩を踏み出したことになります。", nil, nil, 0x8559083b, 0x1984c594, 0x3d58e45a, nil, nil, "...mm" },
  [92471] = { "Aetheen of the Gales", "Thendal GroveにいるAetheen of the Galesと話してください。", "気づいていないかもしれないが、君がしてきたことはすべて、ある種の試練だった。君にこれから訪れることへの試験だ。外は広い島だ。我々の民が直面する試練を生き延びるには、Zephrasには君のような元気な若い冒険者が必要なんだ。\n\nAetheen of the Galesと呼ばれる方は、ここZephras Isleの我々の民の指導者の一人で、君のことを見ていた。君が果たさねばならない任務がある。彼女と話して詳しく聞いてくれ。", nil, nil, 0x09ec0d2f, 0xe70eafd5, 0x8e0f8a1b, nil, nil, "...mm" },
  [92472] = { "次の一歩", "Shen'dar VillageにいるConstable Aondaに報告してください。", "Zephras Isleで最も広く蔓延している脅威の一つが、Al'Aketh Cultだ。彼らは、Skywallの元素の支配者とされるAl'Akir the Windlordの崇拝に身を捧げた狂信者だ。残忍で一途で、その力と野心は日に日に危険を増している。\n\n君の道はまもなく南のShen'dar Villageへと続く。着いたらConstable Aondaのもとへ出向いてくれ。教団がShen'darを脅かしていて、彼らは助けを必要としている。私が君をよこしたとAondaに伝えてくれ。", nil, nil, 0x95c6443c, 0x8dffe20b, 0x6a4b31af, nil, nil, "...mm" },
  [92473] = { "攻撃的な侵食", "Thendal GroveのScrawny UrseraからScrawny Ursera Clawを6個集めてください。", "南西のurseraの巣が急速に問題になりつつある。つい先週も、村に近づきすぎた若いurseraを、レンジャーたちが倒さねばならなかった。そいつは村の中心の長老の木の根元近くで遊んでいた少年を襲おうとしたのだ。\n\n少年が命からがら逃げられたのは幸運だった。飢えと追い詰められた状況が、この獣たちを放っておくには危険すぎる存在にしている。南へ向かい、urseraの中でも最も痩せこけたものを仕留めてくれ。終わったら、証としてその爪を持ってきてくれ。", nil, nil, 0xa8134a87, 0xed3aad19, 0xabd8d5eb, nil, nil, "...mm" },
  [92474] = { "華麗に落下", "Thendal Groveの見張り塔の頂上から飛び降り、Walk on Airの能力で落下を遅くしてください。", "やあ、{name}！ ゲームをしない？\n\nあの岩棚に上って……跳ぶだけ！ 生まれ持った空を歩く力で落ちるのを遅くして、どれだけ前まで漂っていけるか試してみて。\n\nルールは適当だし点数も関係ないけど、Rorian the Dayseekerのすぐ目の前に着地して驚かせたらボーナス点だよ！ 彼は嫌がるだろうけど、彼をかんかんにさせられたら、私は大笑いできるからね！ はは！", nil, nil, 0x5a1c5b0a, 0x102a754b, 0xf3cf38d8, nil, nil, "...mm" },
  [92479] = { "Scribbled Letter", "Scribbled Letterを読み、Northshire AbbeyにいるTordrin Stembladeと話してください。", "kobold野営地から戻ったらすぐにこれを知らせるよう頼まれていたんだ、{name}。地元のハンターのトレーナー、Tordrin Stembladeの印で封をされた手紙のようだ。ここAbbeyで他の用事に取りかかる前に、少し時間を取って読んでくれ。", nil, nil, 0x342ae89e, 0x0b04f03c, 0xaf9dc7c3, nil, nil, "...mm" },
  [92480] = { "zzOLD UNUSED Cult Ambush", "Orders from the High PriestessをShen'Dar Villageへ持って行き、そこの責任者に渡してください。", "今倒した教団員が、Cult of Al'Akirの高位の女祭司からの命令書らしきものを落とした。Shen'dar Villageにいる密偵と、Falaath Villageという場所での教団の活動について書かれている。Shen'dar Villageの当局はこれを知りたがるだろう。", nil, nil, 0xa0dc56ab, 0xc6d5f21e, 0x56bd77c7, nil, nil, "...mm" },
  [92481] = { "秘術の学徒", "Glowing Recall Crystalを調べ、Thendal GroveにいるDorii Brightwhisperと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むメイジのトレーナー――Dorii Brightwhisper――がこのrecall crystalを君に残していった。何か君宛ての伝言が入っているようだから、見てみてくれ。そのあと、Doriiは私のすぐ後ろの建物にいる。", nil, nil, 0xb3167a7d, 0x24eb4049, 0x40084095, nil, nil, "...mm" },
  [92482] = { "ハンターの道", "Scribbled Noteを読んでから、Thendal GroveにいるTai'ree Farsightと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むハンターのトレーナー――Tai'ree Farsight――がこのメモを君に残していった。彼女は村の中心近くのすぐ向こうにいる。メモを読んでから彼女を訪ねてくれ。", nil, nil, 0x66968684, 0x8ac97a8b, 0x21034971, nil, nil, "...mm" },
  [92483] = { "影こそ我が家", "Simple Noteを読んでから、Thendal Groveの見張り塔の中にいるAkeri Duskbladeと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むローグのトレーナー――Akeri Duskblade――が君と話したいと言ってきた。このメモを残していったから、まずそれを読んで、ここ村の見張り塔の中にいる彼を訪ねてくれ。\n\n怪しげな奴だが、まあ、それは君も同じだ。うまくやっていけると思うよ。", nil, nil, 0xc76ec0d0, 0x9787d613, 0x78f1d36a, nil, nil, "...mm" },
  [92484] = { "精霊を受け入れる", "Humming Recall Crystalを調べてから、Thendal GroveにいるWindshaper Boroと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むシャーマンのトレーナー――Windshaper Boro――がこのrecall crystalを君に残していった。調べてみてから、村の中心近くのすぐ向こうにいるBoroと話してくれ。", nil, nil, 0x935b0512, 0x59945334, 0x7abfcd0a, nil, nil, "...mm" },
  [92485] = { "自然の学徒", "Folded Parchmentを読んでから、Thendal GroveにいるXyton Silverwindと話してください。", "君が我々のvuldrenの問題に対処している間に、ここに住むドルイドのトレーナー――Xyton Silverwind――がこのメモを君に残していった。できるだけ早く読んで、それから私のすぐ後ろにあるこの大樹の一階にいるSilverwindを訪ねてくれ。\n\n彼の言葉と助言に耳を傾けるんだ。多くを教えてくれるだろう。", nil, nil, 0x0911d9ff, 0xd2ab2b7f, 0xd328174b, nil, nil, "...mm" },
  [92514] = { "Shen'dar Villageへようこそ", "Shen'dar VillageにいるIllaya AmberwindとCoriella Calmbreezeと話してください。", "君には「Windshaper」の雰囲気があるね。精霊に触れた者の近くにいると、肌に少し静電気を感じるんだ。それで分かるのさ。ここで本格的に働いてもらう前に、ここに住むWindshaperの長老、Illaya Amberwindに挨拶しておくといい。すぐ外の、町の中心近くにいるよ。\n\nああ、それとCoriella Calmbreezeにも顔を出しておいて。地元の宿屋をやっていて、必要なら宿と物資を用意してくれる。", nil, nil, 0x4c9d3c02, 0x5fceeb47, 0x1a5e7e29, nil, nil, "...mm" },
  [92515] = { "Prideclawsの問題", "Shen'dar HighlandsのPrideclawからPrideclaw Peltを10枚集めてください。", "山賊や狂った教団員だけでも手一杯なのに、今は丘にprideclawsもうじゃうじゃいる。村の境界に入り込み始めていて、日に日に大胆になっている。誰かのペットや子供がさらわれるのは時間の問題だ。何か悲劇が起きてからではなく、今のうちに数を減らしておくのが我々にとって慈悲というものだ。\n\n奴らの毛皮を12枚ほど持ってきてくれ。村の役に立ついろいろな品に作り替えられる。", nil, nil, 0x60e9e4a1, 0x42c57bf7, 0xa20f234c, nil, nil, "...mm" },
  [92516] = { "Hippogryphの嫌がらせ", "Shen'dar HighlandsでHippogryph Youthを8体、Hippogryph Protectorを6体、そしてHippogryph Matriarchを倒してください。", "Hippogryphの群れが最近Shen'dar Villageの南東に巣を構え、街道の旅人に大きな被害を与えている。誰かにそこへ行って数を減らしてもらいたい。", nil, nil, 0x941a320d, 0x6f2bf4cf, 0xe1a423dd, nil, nil, "...mm" },
  [92517] = { "犯罪分子", "Shen'dar HighlandsでHighlands Banditを10人と、その頭目の\"Badwind\" Bennicを倒してください。", "北のそう遠くない所に、滝の裏に隠れた洞窟がある。山賊の一団がその洞窟を根城にしていることは、私もよく知っている。教団が来る前から厄介な連中だったが、今では本当の恐怖になっている。残念ながら、奴らを掃討しに行かせる人手を割けないんだ。\n\nそこへ行って、奴らを片付けてほしい。できるだけ多く倒し、できれば奴らの頭目、「Badwind」Bennicと呼ばれる者を始末してくれ。あの洞窟は危険だから、気をつけて。", nil, nil, 0x40976c8d, 0xe1a7ec6c, 0x08ef374d, nil, nil, "...mm" },
  [92528] = { "信徒たちの中で", "Falaath Villageの周辺を調べ、Shen'dar Highlandsでの教団の狙いを突き止めてください。", "君のような熱心な新入りが加わるたびに、Al'Akirの信徒はますます強くなる。見ての通り、我らの力は嵐そのものに形を与えるのだ！\n\n普段ならすぐにSkypriest Aandersのもとへ審査に送るところだが、彼は今、町の北側の宿屋で客人を迎えていて手が離せない。今はそこに近づかないでくれ。君のような髭も剃っていない新入りがそのような客人の前に出るのは不適切だ。\n\n今のところは、とにかく誰の邪魔もしないように。", nil, nil, 0x204012e1, 0x8419ec91, 0xaaed2c17, nil, nil, "...mm" },
  [92529] = { "Falaath Village", "Falaath Villageの入口近くにいるMissionary Jasaanに報告してください。\n\nMark of Akirの効果を失ったら、Shen'dar VillageにいるSania Silverstreamと話して効果を取り戻してください。", "あなたがAl'Akirに仕えたいと願っていることを、心から嬉しく思います。民としての我々の今の試練は、我々自身の慢心から生じたものです。我々は傲慢になり、風の恵みを当然のものと思っていました。その後に続いた停滞こそ、風の精霊たちが我々を見捨てた理由なのです。\n\n悔い改めの行いを通してのみ、我々は再び風の愛撫を感じられるのです。同じ志を持つshen'doreiの仲間を求めるなら、Falaath Villageへ行き、そこにいるMissionary Jasaanを訪ねなさい。信徒たちがあなたを新入りと分かるよう、印をつけておきましょう。", nil, nil, 0x20d8f218, 0x4a06c83e, 0x47085e11, nil, nil, "...mm" },
  [92532] = { "ウォリアーの道", "渡されたCrumpled Noteを読み、Thendal Villageの見張り塔の中にいるBlademaster Renを探してください。", "君がいない間に、ウォリアーのトレーナー――Blademaster Ren――が、君が戻ったら自分のところへよこしてほしいと頼んできた。彼女はこのメモも君のために置いていった。\n\n読んでから、村の見張り塔の中にいるBlademaster Renを訪ねてくれ。", nil, nil, 0x72377474, 0x2103fb1b, 0x3cff1264, nil, nil, "...mm" },
  [92534] = { "jktestquest1a", nil, nil, nil, nil, 0x0b64e98b, nil, nil, nil, nil, ".mmmm" },
  [92544] = { "Al'Akethのごろつき", "Thendal GroveでAl'Aketh Bruteを6人、Al'Aketh Neophyteを4人、そしてMalduko Cloudcrushを倒してください。", "Al'Aketh cultのならず者の一団が、ここから南西の神殿の廃墟近くに住み着いている。率いているのはMalduko Cloudcrushという本物の怪物だ。この連中は間違いなく、Shrine of AkirのHigh Priestess Lorthunaによってここへ送り込まれ、旅人を襲い、我々の民を脅して教団に加わらせようとしているのだ。\n\n私はここの持ち場に留まって、森を出ていく旅人に危険を知らせねばならない。だが、あの教団員どもとその頭目を何とかしてくれたら、ありがたい。", nil, nil, 0x0dea7326, 0xf2db9fef, 0x02f45348, nil, nil, "...mm" },
  [92550] = { "高地の騒乱", "Falaath Villageの廃墟へ行き、Al'Aketh Stormcallerを6人とLiving Lightningを4体倒し、Commander Cyclasの首を手に入れてください。", "ここでの最善の防御は、強力な攻撃かもしれない。今の我々の強みは、攻撃が来ると分かっていることだ。奴らが予想していないのは、我々が先に仕掛けることだ。\n\nすでに多くを頼んでしまったが、どうかFalaath Villageへもう一度向かってくれ。できるだけ多くの教団員を倒し、近づけるなら指揮官を倒してその首を持ってきてくれ。私はここに残って、住民と数少ない治安維持隊をまとめて防衛の準備をする……万が一、君が戻らなかった時のためにな。", nil, nil, 0xac4c0e34, 0x9fc6a9c3, 0x20b41f51, nil, nil, "...mm" },
  [92551] = { "Stolen Supplies", "Shen'dar HighlandsのFalaath VillageからStolen Shen'dar Suppliesを10個集めてください。", "Falaath Villageに行くかもしれないって聞いたんだけど？ そこにいる間、盗まれた私たちの補給物資の隠し場所に目を光らせておいて。\n\nAl'Akethは何か月も前から、食料やwindstonesなどいろいろな品を低地と行き来させる私たちの補給隊を襲っているんだ。もちろん山賊のせいにしているけど、結局は全部同じ場所に行き着くって、みんな分かってる。Falaathにその品が少しでも残っていたら、取り戻してくれるととても助かる。", nil, nil, 0x97ab9949, 0x20dd891c, 0x781e5b88, nil, nil, "...mm" },
  [92553] = { "食料庫の補充", "Shen'dar Highlands各地の生き物からSmall Eggを$N1個とStrider Meatを$N2個集めてください。", "ちょっと仕事をしないか？ 君みたいな強い冒険者タイプの腕っぷしを借りたいんだ。このあたりがこんなに物騒になってきたせいで、最近は誰も狩りや採集をする暇がなくてね。この村を食べさせていくために、外へ出て新鮮な卵とstrider meatを調達してくれる人が必要なんだ。\n\n必要なものを持ってきてくれたら、私の有名なレシピを1つ喜んで教えるよ。どうだい？", nil, nil, 0x5295b2aa, 0xd69fc243, 0xf0409ea7, nil, nil, "...mm" },
  [92579] = { "Valanaarへ", "Aonda's Written ReportをValanaarにいるValennia Stormfistに届けてください。", "今のところパイロンも村も無事のようだから、この報告書を島の南東の端にあるValanaarのValennia Stormfistに届けてほしい。Valenniaは島の治安維持隊の長で、ここで何があったか知っておく必要がある。\n\n教団は急速に勢力を広げている。治安維持隊はこれまで直接の衝突を避けてきたが、そんな日々はもう終わりだ。Valanaarは戦いに備えなければならない。\n\nともかく、ありがとう。Shen'darにはいつでも君の友がいる、{name}。", nil, nil, 0x74fef55e, 0x117fb641, 0xabb0a4f6, nil, nil, "...mm" },
  [92595] = { "Windshapers", "Illaya Amberwindの話を聞いてください。", "<Illayaがあなたに温かく微笑む。>\n\nよく戻って話しに来てくれました、風の子よ。あなたが初めて私の前に現れた瞬間から、あなたがskysightに秀でていると分かっていました。驚きましたか？ シャーマンとしての修行を積んでいない者でも、この才を持つことがあるのです。\n\nさあ、Windshapersの使命、Zephrasにおける我々の苦闘の本質、そして我らが民の苦境について話しましょう。", nil, nil, 0x780f72d7, 0xc822e25f, 0x377f999c, nil, nil, "...mm" },
  [92596] = { "High Order", "席に着いて、Rathiril Sunlanceと話してください。", "あなたを取り巻く秘術のエネルギーのオーラは強い。メイジとしての手ほどきを受けていないにもかかわらずです。あなたはきっと有能な冒険者になるでしょう。たとえ呪文を唱えるための力ある言葉を一言も発することがなくとも、我らの古の魔法とのつながりは、あなたにとって恩恵にしかならないはずです。\n\nさあ、座って、私の結社のこと、ここZephrasにおける秘術の本質、そして我らが民の苦境について少し話しましょう。", nil, nil, 0x022195d4, 0x8d1edbd7, 0xfb71220a, nil, nil, "...mm" },
  [92597] = { "レイラインを読む", "Thendal Groveの地脈で、種族能力Read Ley Lineを使ってください。", "ここ元素界では、我々は秘術の力の多くを、今も足元の地中を走るレイラインから得ています。最近、これらのレイラインが地表を突き破り始め、潜在する秘術のエネルギーに、より直接的かつ強力に触れられるようになりました。\n\n北東の立石へ行ってください。そこにレイラインがあります。生まれ持った力を使い、そのエネルギーを取り込みなさい。", nil, nil, 0xb27b6c1c, 0xa07cd5b4, 0x5d755957, nil, nil, "...mm" },
  [92598] = { "Skysightの贈り物", "Thendal GroveのElemental Convergenceで、種族能力Skysightを使ってください。", "Windshaperとして、あなたには元素の精霊たちから我々に授けられた神聖なskysightを使う力があります。村の北東の立石へ向かってください。そこで元素の合流点を見つけ、その才を使いなさい。\n\nskysightはどこでも使えますが、元素の合流点のそばで使えば、その恩恵ははるかに強くなることが分かるでしょう。そうした力の場に引き寄せられる精霊たちから、時には他の知恵を授かることもあるはずです。", nil, nil, 0x72459b2b, 0x16d8780d, 0x316bc5c0, nil, nil, "...mm" },
  [92640] = { "窮地", "ValanaarにいるValennia Stormfistと話し、彼女の指示に従ってください。", "教団と正面から戦うのは現実的ではないから、この機会を使って聖堂そのものを攻撃するのが最善の手だろう。Lorthunaが計画の自分の役割を果たす前に、彼女自身を盤上から除けるかもしれない。\n\nちょうど、Valenniaがしばらく前からShrineへの攻撃に備えた作戦を練っていた。唯一の問題は、助けが必要だということだ。\n\n詳しいことはValenniaと話してくれ。", nil, nil, 0xbee67de8, 0xe0ffb7d6, 0x807c5f5e, nil, nil, "...mm" },
  [92642] = { "兵站の妨害", "Gustberry LowlandsでAl'Aketh Healerを4人とAl'Aketh Brawlerを8人倒してください。", "Valenniaは本格的な攻撃を撃退するのに、たった1人しか送ってこなかったのか……風にかけて。\n\n大した奴には見えないが、贅沢は言えない。すぐにこれを止めるには、できるだけ大きな損害を与える必要がある。私の部下たちはもう長くは持ちこたえられない。\n\n丘を下りて、奴らの補給を乱してくれ。奴らの治癒師が攻撃者を送り続けている。治癒師を片付ければ、態勢を立て直して押し返せるかもしれない。そこで他の教団員を倒してくれるのも助かる。", nil, nil, 0x4ee49cde, 0xfd87bd08, 0x9d51a92f, nil, nil, "...mm" },
  [92643] = { "裏切り者", "Valanaarの北西、高地に入ってすぐの家にいる教団の裏切り者を見つけてください。", "Al'Akethの中に裏切り者がいる。そいつは教団の島に対する真の意図を知っていると言い、こちらに投降したがっているが、身の安全の保証がなければ来ないそうだ。\n\nこの離反者は、Valanaarのすぐ北西、高地の中の人里離れた住居に隠れている。誰か目立たずにそこへ行き、裏切り者を見つけて、我々のもとまで護衛してきてほしい。罠かもしれないが、この情報が裏切り者の言うほど重要なら、多少の危険を冒す価値はある。", nil, nil, 0x19e86215, 0xbb45643c, 0x813bb0ca, nil, nil, "...mm" },
  [92644] = { "不運な知らせ", "光る水晶をValanaarにいるTalanaanis Shadowsongに届けてください。", "<まだ温かい裏切り者の教団員の遺体の下に手を伸ばし、小さく青く光る水晶を拾い上げた。傷ついているようだが、まだ重要なものかもしれない。High Elder Shadowsongがこれに興味を持つかもしれない。>", nil, nil, 0xfee67657, 0xd4f77d59, 0x29c73863, nil, nil, "...mm" },
  [92645] = { "the Breakerの打倒", "Gustberry LowlandsでCommander Belguilosを倒してください。", "教団の指揮官を倒さない限り、この攻撃を撃退するのは難しいだろう。Belguilos「the Breaker」と呼ばれている女で、まさに恐怖そのものだ。教団が手に負えなくなる前は治安維持隊の一員だったが、その頃から彼女は……どこかおかしかった。教団員となった今、どれほどひどくなっているか想像もつかない。\n\n君を死地に送り出すことになるかもしれないが、ここで生き延びるには誰かがBelguilosを倒さねばならない。彼女は丘のふもとの屋敷にいる。幸運を、{class}。", nil, nil, 0xe9120191, 0x51edce72, 0x069c8615, nil, nil, "...mm" },
  [92646] = { "Lorthunaとの対決", "ポータルで頭上のRohashi Spiresへ行き、Elaadrin EvengaleとAyessa Dawnsingerに加わってHigh Priestess Lorthunaと対決してください。", "Lorthunaは何かのポータルを使って上の尖塔へ逃げた。AyessaとElaadrinが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、Ayessaを見つけ、彼らがLorthunaを止めるのを手伝ってくれ。\n\nElaadrinとAyessaが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。", nil, nil, 0x90290d9d, 0x05b5bc13, 0xc9ea1d15, nil, nil, "...mm" },
  [92679] = { "血の十分の一税", "Alvarion Windfieldの話を聞き、Windfield OrchardにいるAamelia Windfieldを見つけてください。", "こ……こんにちは、見知らぬ方。有能な冒険者のようにお見受けします。私は……\n\n<Skyborneの男は顔をしかめる。明らかにひどい痛みに苦しんでいる>\n\n……仕事を探しておられないかと思いまして。私は農場を救うために戦える者を集めようと、ここValanaarへ来ました。もし興味がおありなら、Valanaarの西、低地にある果樹園にいる妻のAamelia Windfieldを訪ねてください。", nil, nil, 0xa8fc6a6e, 0x914a33e3, 0x14a8cf7d, nil, nil, "...mm" },
  [92682] = { "役に立つこと", "Windfield OrchardでRipe Stormappleを10個集め、Hungry Banditを5人倒してください。", "あら、分別より度胸があるってわけ？ いいわ、反対はしない。\n\nFerauuとその手下どもが収穫の取り分を取りに来るのはまだ先だから、奴らが来るまで食事代として働いてもらうわ。\n\n外へ出て、今日の分のstormapplesを集めてきて。ああ、それとstormappleの木の周りに潜んでいる山賊ども……こっそりしてるつもりなのよ。全然そうじゃないけど。そいつらを倒してきて。\n\n戦いでどれだけやれるか見せてもらうわ。", nil, nil, 0x465218e3, 0x7a8714e9, 0x7b15cb2a, nil, nil, "...mm" },
  [92683] = { "Flutterfly Dust", "Gustberry Lowlands周辺のFlutterfliesからFlutterfly Dustを5個集めてください。", "果樹園の外れの畑に巨大なflutterfliesがいるのに気づいたでしょう？ 見た目もいいけど、他にも役に立つの。つまり、羽の粉よ。散らかるけど、たくさん集められれば家庭でいろいろ使えるの。\n\nこのFlutterfly Swatterを持っていって、あの大きな虫をひっぱたいてきて。たいていは驚いて逃げるだけだけど、たまに怒ることもあるわ。どちらにしても、お尻を振って粉の山を落としていくはずよ。", nil, nil, 0xebc0dbf4, 0x62baa758, 0x70511ad5, nil, nil, "...mm" },
  [92684] = { "気難しい気難しいGalestriders", "Gustberry Lowlands各地にいるOrnery GalestriderからLowlands Galestrider Tenderloinを7個集めてください。", "今年はただでさえ収穫が少ないのに、このあたりのgalestridersが果樹園に入り込んで私のstormapplesを盗んでいくの。畑へ行って、数を減らしてきてくれない？\n\nでも気をつけて、よそ者さん。この低地のgalestridersは高地のものより大きくて気が荒いの。油断しないで。注意していないと、うまく決まった蹴り一発で永遠に倒されてしまうわ。\n\n奴らの肉を持ってきてくれたら、それで温かい食事も作れるわ。", nil, nil, 0xe003ddda, 0xac246e35, 0xd896bad6, nil, nil, "...mm" },
  [92685] = { "丘に目あり", "Gustberry LowlandsのHighwayman BanditからBlood-Stained Bandit Maskを7枚奪ってください。", "山賊どもはあちこちに野営地を持っていて、ここのすぐ北の丘にも小さいのがある。そこへ行って、頭をかち割ってきて。不意を突いて、向こうが来る前に倒せれば、勝ち目が出るくらいには形勢を互角に近づけられるかもしれない。\n\n奴らの覆面を持ってきて。血まみれなほどいいわ。", nil, nil, 0x68a565d3, 0x0cc48551, 0x0d447ad8, nil, nil, "...mm" },
  [92693] = { "踏みとどまる", "山賊の頭目と対決する準備ができたら、Aamelia Windfieldと話してください。", "あなたは私たちに戦うチャンスを与えるために、たくさんのことをしてくれた。たとえ今日死んでも、少なくとも全力を尽くしたとは分かるわ。\n\nこれが最後のチャンスよ、よそ者さん。Valanaarへ戻ってもう一日生き延びたいなら、責めはしない。\n\n一方で、本当に負け戦が好きなら、準備ができたら教えて。胸を張って出ていって、何が起きようと、それはそれよ。", nil, nil, 0x50b105ba, 0x080cc4f1, 0xdb57333a, nil, nil, "...mm" },
  [92698] = { "私の目的とは？", "Malfunctioning Cyclone Constructについて、Aamelia Windfieldと話してください。", "<巨大な構造体の装甲板の下から聞こえてくる言葉を聞き取ろうと、身を寄せる。>\n\n……機能エラー……\n\n……質問……\n\n……何とは……\n\n……機能……\n\n<断片的な言葉や語句が繰り返されているだけのようだ。近くの誰かがこの構造体についてもっと知っているのでは？>", nil, nil, 0x241171d6, 0xd478b4f6, 0x3666770b, nil, nil, "...mm" },
  [92699] = { "至高のMagister", "ValanaarにいるElaadrin Evengaleを見つけてください。", "Valanaarに着いたなら、ここにいるHigh Orderの他の仲間たちに顔を出しておきたいだろう。今のSupreme Magister、Elaadrin Evengaleとその部下たちは、Valanaarの南東の端の山荘を拠点にしている。\n\nそれと、気をつけるといい。ここではHigh OrderとWindshapersの仲が良くない。用心して、Windshapersには十分距離を置くことだ。教団だけでも心配事は十分ある。Valanaarの通りで派閥同士の暴力沙汰は許さない。", nil, nil, 0x395f1c03, 0x81508f78, 0xc13b19e1, nil, nil, "...mm" },
  [92700] = { "Grand Skyseer", "ValanaarにいるAyessa Dawnsingerを見つけてください。", "Valanaarに着いたなら、ここにいるWindshapersの他の仲間たちに顔を出しておきたいだろう。今のGrand Skyseerとその部下たちは、Valanaarの中心近くの山荘を拠点にしている。\n\nそれと、知っておくといい。このあたりではWindshapersとHigh Orderの仲が良くない。用心して、High Orderには十分距離を置くことだ。教団だけでも心配事は十分ある。Valanaarの通りで派閥同士の暴力沙汰は許さない。", nil, nil, 0x0b95857e, 0x5fb884e9, 0xe4a12cfa, nil, nil, "...mm" },
  [92701] = { "Valanaarへ", "Aonda's Written ReportをValanaarにいるValennia Stormfistに届けてください。", "今のところパイロンも村も無事のようだから、この報告書を島の南東の端にあるValanaarのValennia Stormfistに届けてほしい。Valenniaは島の治安維持隊の長で、ここで何があったか知っておく必要がある。\n\n教団は急速に勢力を広げている。治安維持隊はこれまで直接の衝突を避けてきたが、そんな日々はもう終わりだ。Valanaarは戦いに備えなければならない。\n\nともかく、ありがとう。Shen'darにはいつでも君の友がいる、{name}。", nil, nil, 0x74fef55e, 0x117fb641, 0xabb0a4f6, nil, nil, "...mm" },
  [92703] = { "知らせの配達", "ValanaarにいるAlvarion Windfieldと話してください。", "これだけのことがあったのに、あなたをよそ者と呼び続けるのはどうもしっくりこないわね。だから……ありがとう、{name}。\n\nもしよければ、そっちへ戻ることがあったら、ここで何があったかAlvarionに伝えて。それと、あの人が立てるようになったら、windshaperを一人ここへ連れてきて、あの構造体を調べてもらうよう言って。私たちの……私たちの家族のそばに置いても安全か確かめたいの。\n\n<Aameliaがそっとお腹に触れる。>\n\nこのことはあの人は知らないの。今はここだけの話にしておきましょう。", nil, nil, 0xa7d041e9, 0xd93e176f, 0x41c99c84, nil, nil, "...mm" },
  [92706] = { "お尋ね者：Bruuz", "Bruuz's Dorsal FinをRatchetにいるGazloweのところへ持って行ってください。", "釣り人諸君に告ぐ！\n\n巨大なサメが船着き場近くの海域を回遊し、船乗りや小舟を襲っている。港湾労働者たちはそいつに「Bruuz」というあだ名をつけた。そのヒレを持ってきた者には、たっぷりと報酬を出すぞ！\n\n-- Gazlowe", nil, nil, 0x63f4d985, 0xf267f662, 0xc0d6b34c, nil, nil, "...mm" },
  [92708] = { "大冒険", "Ayessa Dawnsingerの話を聞いてください。", "Windshapersは、Zephras Isleの現在の危機に対処しようと懸命に働いてきました。消えた風の精霊を探す中でいくつか驚くべき発見があり、島を救う手段を得る助けになりうる行動計画を練っているところです。\n\nただし、これを成功させるには、あなたのような強い若い冒険者が必要です。どうか、少しお時間があれば、このことについてさらにお話しさせてください。", nil, nil, 0xd900e63a, 0x9a2edad6, 0x974a5ecf, nil, nil, "...mm" },
  [92709] = { "大冒険", "ValanaarにいるElaadrin Evengaleの話を聞いてください。", "あなたのhighborneの血筋は、頭上の空のようにはっきりとその瞳に輝いています。あなたは我々の一員であり、我々の故郷を救う助けとなるのは、あなたのような若者なのです。ですがまずは、ここZephrasでの……そしてその先での、我々の使命と計画についてもっとお話しさせてください。", nil, nil, 0xd900e63a, 0x8e1740b2, 0xbb915068, nil, nil, "...mm" },
  [92727] = { "行方不明の学者", "Fillion Flamebreezeの身に何が起きたのか突き止めてください。", "知識の探求はHigh Orderの第一の使命ですが、この仕事が今のZephrasほど危険だったことはありません。\n\n我々の学者の一人、Fillion Flamebreezeは、Shen'dar Highlandsの一部の地域に集まる風の魔法について調査するため、そこへ向かう途中でした。残念ながら彼は戻っておらず、道中で何かあったのではと案じています。\n\nできることなら、彼を探し出してください。最後に目撃されたのは、ValanaarからShen'dar Highlandsへ西に向かう道の上でした。", nil, nil, 0xa1e8590e, 0xd1671205, 0x24478d54, nil, nil, "...mm" },
  [92741] = { "招かれざる訪問者", "Shadowgale Forestへ行き、ValanaarにいるIaadaria BitterwindのためにShriekling Talonsを8個集めてください。", "Shadowgale Forestはとてつもなく危険で、普通の冒険者は通常立ち入りを禁じられています。ここ数か月でshrieklingの数が爆発的に増え、森の外へ縄張りを広げ始めていて、問題になりかねません。私はshriekling talonsの錬金術的な性質に関心があるので、どうしても必要な間引きは、学術的な収穫を得る機会でもあるのです。\n\nShadowgale Forestへ行って、その獣を狩ってください。できるだけ多くの爪を持ってきてください。", nil, nil, 0x3ef89823, 0xc2afbc22, 0x9ce8f981, nil, nil, "...mm" },
  [92742] = { "井戸の調査", "Well Water Sample Kitを使って、Jansen SteadとMolsen Farmの井戸から水のサンプルを採取してください。", "この地を蝕む毒の源と正体を突き止めねばならない。まずはこの辺りの農場の地下水から始めよう。\n\n北のJansen Steadと、ここから北西のMolsen Farmへ行き、そこの井戸から試料を集めてくれ。", nil, nil, 0x1754ed02, 0xbfaa968d, 0x8ee73e39, nil, nil, "...mm" },
  [92744] = { "Murlocのエラ", "Alba Fairmoonは、Westfallの海岸線沿いでLongshore Murloc Gillを7個集めてほしいと言っています。", "Westfallの作物を冒している汚染は、海にもしみ出しているかもしれません。地元の魚まで影響を受けていたら、Stormwindは飢饉に見舞われかねません。\n海岸沿いのmurlocsからgillsを集めて、持ってきてください。Murlocsはとても丈夫ですが、その体は汚染物質に非常に敏感です。海水に毒があれば、集めたgillsにはっきり表れるはずです。", nil, nil, 0x18d085b1, 0x82b38f95, 0x84c4b3d3, nil, nil, "...mm" },
  [92745] = { "鉱山の状況", "Jangolode MineでKobold Diggerを4体、Gold Coast QuarryでRiverpaw Minerを6体倒してください。", "集めてくれた井戸の試料には有毒な金属が含まれています！ この汚染をすぐに止めなければ、この土で再び作物が育つまで何十年もかかるでしょう。\nDefiasがWestfallの鉱山を占拠し、生き物を働かせて資源を奪い取っています。北のJangolode Mineと西のGold Coast Quarryで奴らの鉱夫を倒して、邪魔をしてください。", nil, nil, 0xdbfbda3d, 0xb4f30bb0, 0x0ed0182f, nil, nil, "...mm" },
  [92747] = { "Moonbrookの諜報活動", "MoonbrookからSuspicious Industrial Suppliesを8個集めてください。", "妙ですね――毒はあなたが調べた鉱山から出ているのではないようです。\n\nMoonbrookの町の下にあるDeadminesはWestfallで最も大きく深い鉱山だと聞いていますが、First War以来放棄されています。Deadminesが再び動いているのでしょうか？\n\nMoonbrookへ行ってください、{name}。採掘や工業活動の証拠を探してください。これが我々に残された最後の手がかりです！", nil, nil, 0xd607718d, 0x576e6434, 0xbc34590a, nil, nil, "...mm" },
  [92748] = { "爆発物の相談", "StormwindのDwarven Districtへ行き、力を貸してくれる技師を見つけてください。", "あなたが見つけた物資は、Deadminesのどこかで大規模な工業作業が行われていることを示しています。これがWestfallの農地を苦しめている毒の出どころであることは間違いありません。すぐに止めなければ。\n\nあそこにあるものは、壊すのが難しいでしょう。StormwindのDwarven Districtへ行き、爆薬を用意してくれる技師を見つけてください。", nil, nil, 0x35aa9cd8, 0x37ec6835, 0x6c61d133, nil, nil, "...mm" },
  [92749] = { "ダイナマイト作戦", "製作、取引、またはオークションハウスでCoarse Dynamiteを10個手に入れ、StormwindのDwarven DistrictにいるSprite Jumpsprocketのところへ戻ってください。", "産業破壊工作？ 興味が湧いたぞ！\nまずはdynamiteから始めよう……", nil, nil, 0xdbe7a3f6, 0x66c49bdc, 0x9f9816fe, nil, nil, "...mm" },
  [92750] = { "遠隔からの爆破", "遠隔起爆装置の入手について、Stormwind Intelligenceの誰かと話してください。", "「制御された」爆発がお望みなんだろう？ それほど楽しくはないが、手足を全部残しておきたいなら賢い選択だ。\nあいにく遠隔起爆装置は持っていないんだ――Stormwind Intelligenceのこそこそした連中に聞いてみたらどうだ？ 何か見つけてくれるはずだ。", nil, nil, 0x9e430b80, 0x2e22edaa, 0xb2c46b4f, nil, nil, "...mm" },
  [92751] = { "遠隔からの爆破", "Remote Detonator KitをStormwindのDwarven DistrictにいるSprite Jumpsprocketのところへ持って行ってください。", "何かを壊したいのか？ Moonbrookでのお前の行動と何か関係があるのか？ 驚いた顔をするな。SI:7はStormwindの領内で起きることはすべて把握している。\nWestfallの地下の洞窟で爆発を起こすつもりなら、事前に十分外へ出ておくことだ。このremote detonatorを持っていけ――我々の技師が作った最新の試作品だ。\nああ――それと、私が関わったことは、お前のelfの友人には言わないほうがいい。", nil, nil, 0x9e430b80, 0xecf85250, 0xed52dcab, nil, nil, "...mm" },
  [92752] = { "爆発物の相談", "WestfallにいるAlba Fairmoonのところへ戻ってください。", "これでよし――爆弾の準備完了だ！ その起爆装置の扱いには気をつけろよ。", nil, nil, 0x35aa9cd8, 0x767de34f, 0x68df9c9c, nil, nil, "...mm" },
  [92753] = { "Deadminesでの破壊", "Deadminesに隠された鍛冶場を見つけ、その近くにExtra-Destructive Explosivesを仕掛けてください。それから、Deadminesの出口でAlba Fairmoonと落ち合ってください。", "毒の出どころは、おそらく何らかの大型の冶金炉です。Deadminesへの入り口を見つけ、その炉を探し出して、爆薬を仕掛けてください。\nMoonbrookの裏の丘であなたを待っています。戻ってきたら、爆薬を起爆しましょう。炉がなくなれば、この地も癒え始めるといいのですが。", nil, nil, 0x7e9a4fff, 0x13b8e5d8, 0x22098598, nil, nil, "...mm" },
  [92819] = { "Deadminesでの破壊", "起爆装置を使う。", "もうすぐ終わりだ。起爆装置を使って、決着をつけろ。", nil, nil, 0x7e9a4fff, 0x8e3775bb, 0x06a779b6, nil, nil, "...mm" },
  [92834] = { "十倍の報復", "Valanaarの北にあるGustberry FieldsまたはShrine of AkirにいるAl'Akethの教団員から、Al'Aketh Windstone Charmを10個集めてください。", "教団が暴力の運動を始めた時、PeacekeepersとWindshapersは威嚇で応えた。私はそれを愚かな緊張の激化だと考え、平和的な対話を訴えた。昨日、その対話を実現しようと、友人のBelathaan BrightwishをShrine of Akirへ送り出したのだ。\n\nつい先ほど箱が届いた。中には、銀の顔料に浸されたBelathaanの舌が入っていた。\n\n今ならはっきり分かる。教団に道理は通じない。目にした教団員は皆殺しにして、奴らが持っている祈りのお守りを持ってきてくれ。", nil, nil, 0xe040942e, 0xd3397555, 0xdef35c38, nil, nil, "...mm" },
  [92840] = { "風をつかむ", "Index EsoteriaをShen'dar HighlandsのOverlook Standing Stonesへ持って行き、周辺のWindstone Formationsに使ってデータを集める。", "Fillionは、そこにあるエレメンタルのエネルギーを測定し研究するための特別な装置を持って、Overlook Standing Stonesへ送られた。\n\nこれを持っていけ――Index Esoteriaだ。これを使って、あそこにそびえる巨大なwindstoneの岩層からデータを引き出してくれ。ただし用心しろ。Windshaperたちが今ごろこの場所を躍起になって守っているだろうからな。\n\n邪魔しようとする者がいたら、まあ……必要なことをするといい。奴らの妨害にはもう我慢ならん。", nil, nil, 0x24fe5981, 0x3d378073, 0x1389f90b, nil, nil, "...mm" },
  [92849] = { "行方不明の学者", "Fillion Flamebreezeを探し続けてください。", "<今見つけたものから判断すると、Fillionがここで何らかの災難に見舞われた可能性は非常に高い。彼はまだ近くにいて、助けを必要としているかもしれない。今いる場所のすぐ北に洞窟があることに気づく。そこで彼の捜索を続けるべきだろう。>", nil, nil, 0xa1e8590e, 0x1851c7de, 0xba014091, nil, nil, "...mm" },
  [92850] = { "行方不明の学者", "Shriekling DenでShriekling Matriarchを倒し、その首をValanaarのFillion Flamebreezeのところへ持ち帰る。", "もうずいぶん気分が良くなりました。私は秘術にいくらか心得がありますし、Valanaarまではほんの少しの距離です。一人で戻れます。ですが、私の身の安全よりも重要なのは、このshrieklingどもがValanaarのこれほど近くに巣を作っていることと、それがもたらす危険です。よろしければ、もう一度中に入って、あの獣の首を取ってきてください!\n\nそれが済んだら、Valanaarで私を見つけてください。ここで起きたことと、私の任務の状況を、Supreme Magisterに報告しなければなりません。", nil, nil, 0xa1e8590e, 0xbe3aeb06, 0xf66a2b79, nil, nil, "...mm" },
  [92860] = { "Zephrasに仕えて", "Valennia Stormfistに報告し、Al'Akethとの戦いにおいてHigh Orderが彼らと共にあると伝えてください。", "High Orderは教団との直接の衝突を避けるよう最善を尽くしてきましたが、もはやそれは選択肢になりません。彼らの敵意ははっきりと示されましたし、今では島中で教団がより大規模に動いているという噂もあります。明らかに何かに備えていて、それが何であれ、Zephrasの民にとって良いことであるはずがありません。\n\nValennia Stormfistのもとへ行き、必要とあらば、High OrderはAl'Akethに対するValanaarの取り組みを全面的に支援すると伝えてください。", nil, nil, 0x81e9cbc4, 0x3f659549, 0x686ea4c6, nil, nil, "...mm" },
  [92871] = { "Zephrasに仕えて", "Valennia Stormfistに報告し、Al'Akethとの戦いにおいてWindshapersが彼らと共にあると伝えてください。", "Valennia Stormfistと彼女の治安維持隊は、常にZephrasの守り手でした。我々も、できる限り手を貸そうと努めてきました。島中で教団がより大規模に動いているという噂があり、明らかに何かに備えています。\n\nValenniaのもとへ行き、必要とあらば、WindshapersはAl'Akethに対するValanaarの取り組みを全面的に支援すると改めて伝えてください。", nil, nil, 0x81e9cbc4, 0x0b60fad2, 0x09ceb47e, nil, nil, "...mm" },
  [92880] = { "Valanaarのもとへ", "Yorna's ReportをValanaarのValennia Stormfistに届けてください。", "攻撃してきた連中の残りを片付けるには少し時間がかかりそうだが、今なら我々の勝算はずっと高い。Valanaarへ戻って、ここはもう安定したと伝えてくれ。\n\n君の助けには感謝してもしきれない。君がいなかったら、ずっとひどい状態になっていただろう。援軍を頼んだら、代わりに成長著しい英雄が来たようだ。それで十分だ。\n\n4つの風が君を祝福せんことを、{class}。", nil, nil, 0x50dc0d7e, 0xb15128d3, 0x1556d10a, nil, nil, "...mm" },
  [92881] = { "大長老の頼み", "ValanaarのTalaanis Shadowsongと話してください。", "西と東の両方の見張り塔が攻撃されたのは偶然ではない。西の見張り塔であのskypriestとの間に起きたことを君から聞いた限りでは、教団はアンカーパイロンに何かしようとしているのだろうというのが我々の最善の推測だ。\n\nHigh Elder Shadowsongと話してくれ。有望になりうる手がかりについて教えてくれるだろう。", nil, nil, 0xb3d882cd, 0x4440ff8a, 0x1a6cef28, nil, nil, "...mm" },
  [92909] = { "収穫機からの収穫", "Saldean's FarmのOzwin Ironsprocketは、Golem Isospringsを14個とHarvester Gyrostabilizersを5個持ってきてほしいと言っています。", "ああ、しまった……こりゃまずいことになったぞ！\n\nWestfallの畑でharvestersが暴れていると聞いて、調整し直せないかと、はるばるIronforgeから来たんだ。でも、あいつらは私の計算よりずっと凶暴で、この厩舎まで追いかけてきたんだよ！\n\nharvestersからisospringsとgyrostabilizersを手に入れられれば、逃げるのを援護する装置を作れるんだが。部品を集めてきてくれないか？", nil, nil, 0xced8714e, 0xb9cd3180, 0x7c112345, nil, nil, "...mm" },
  [92910] = { "収穫機からの収穫", "Precessive Autocognition AssemblyをSaldean's FarmのOzwin Ironsprocketに届けてください。", "harvesterから回収できたこの部品は、ほぼ無傷のようだ。harvest golemsに関心のある者なら見たがるかもしれない。", nil, nil, 0xced8714e, 0xd39b8561, 0x8ffaa4f3, nil, nil, "...mm" },
  [92911] = { "収穫機からの収穫", "Saldean's FarmのOzwin Ironsprocketは、Golem Isospringsを8個、Copper Modulatorsを4個、それにCrude Scopeを一つ持ってきてほしいと言っています。", "なるほど……これであの怪物どもがどう動いているのか少し分かったぞ。少なくとも一時的には、奴らのシステムを乗っ取る方法を思いついた。\n\n持ってきてくれた組立部品をもう少しいじってみる。その間に、装置の部品をかき集めてきてくれないか？", nil, nil, 0xced8714e, 0x7ea5662a, 0xb1fbfa85, nil, nil, "...mm" },
  [92947] = { "行動開始", "Al'Aketh Guardianを$N1体、Al'Aketh Spiritcallerを$N2体、Al'Aketh Blademasterを$N3体倒し、Shrine of AkirにいるHyusaa Quickbreezeに報告する。", "全員揃ったな、よし。精鋭の戦士を何人か聖堂の正面から突入させて、騒ぎを起こし陽動にさせた。その間に私がWindshapersとHigh Orderを率いて側面から攻め込む。\n\nうまくいけば、すぐに突破してHigh Priestessを倒せるはずだ。君は、中に入って頭をかち割り始めてくれ。騒ぎを起こしたら、聖堂の階段近くで私の副官、Hyusaa Quickbreezeと合流しろ。\n\n風が君を導かんことを、{class}。", nil, nil, 0x688633bd, 0x590637a2, 0xe5240575, nil, nil, "...mm" },
})
